discrete WeldingSystem
port:
    event input real StartSignal;
    event input real MaterialEnter;
    event input real MaterialExit;
    event input real FaultResolved;
    event output real WeldingCompleted;
state:
    initial state InitialState
        when entry() then
            statehold(0);
        end;
        when receive(StartSignal) then
            transition(PreparationState);
        end;
    end;

    state PreparationState
        when entry() then
            statehold(0);
        end;
        when receive(MaterialEnter) then
            transition(WeldingState);
        end;
    end;

    state WeldingState
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(CompletionState);
            out
                send(WeldingCompleted, 1);
        end;
    end;

    state CompletionState
        when entry() then
            statehold(0);
        end;
        when receive(MaterialExit) then
            transition(PreparationState);
        end;
    end;

    state FaultState
        when entry() then
            statehold(0);
        end;
        when receive(FaultResolved) then
            transition(PreparationState);
        end;
    end;
end;
end;

